-- PostgreSQL: minimale Tabelle und Abfrage
CREATE TABLE greeting (
  id   SERIAL PRIMARY KEY,
  text TEXT NOT NULL
);

INSERT INTO greeting (text) VALUES ('Hallo, Welt!');

SELECT text FROM greeting;

codeExamples.tech2Snippet:
-- Apache Cassandra: Keyspace, Tabelle und Abfrage (CQL)
CREATE KEYSPACE IF NOT EXISTS demo
  WITH replication = {'class': 'SimpleStrategy', 'replication_factor': 1};

USE demo;

CREATE TABLE IF NOT EXISTS greeting (
  id   int PRIMARY KEY,
  text text
);

INSERT INTO greeting (id, text) VALUES (1, 'Hallo, Welt!');

SELECT text FROM greeting WHERE id = 1;
